// Structs derive Debug, Clone, PartialEq (WorkflowPolicy's Value
// prevents Eq). WorkCatalog derives Debug, Clone. Lookups are linear
// scans with iterator find - the catalog is small and frozen.
// Tests in-file: build a two-project catalog; profile/recipe/workflow
// lookups hit and miss exactly.

signature:
pub struct AgentProfile {
    pub name: String, pub backend: String, pub model: String,
    pub transport: String, pub modes: Vec<String>,
}
pub struct Recipe { pub id: String, pub digest: String }
pub struct WorkflowPolicy { pub digest: String, pub document: serde_json::Value }
pub struct ProjectCatalog {
    pub alias: String, pub profiles: Vec<AgentProfile>,
    pub recipes: Vec<Recipe>, pub workflow: Option<WorkflowPolicy>,
}
pub struct WorkCatalog { /* private: projects: Vec<ProjectCatalog> */ }
impl WorkCatalog {
    pub fn new(projects: Vec<ProjectCatalog>) -> WorkCatalog;
    pub fn project(&self, alias: &str) -> Option<&ProjectCatalog>;
    pub fn profile(&self, alias: &str, name: &str) -> Option<&AgentProfile>;
    pub fn recipe(&self, alias: &str, id: &str) -> Option<&Recipe>;
    pub fn workflow_digest(&self, alias: &str) -> Option<&str>;
    pub fn projects(&self) -> &[ProjectCatalog];
}
